<?php
namespace App\Domain\Governance\Services;
use App\Domain\Audit\Services\AuditRecorder;use App\Models\{Document,DocumentLegalHold};use Illuminate\Support\Facades\DB;
class LegalHoldService{public function place(Document $document,string $reason,?string $authority,int $actor):DocumentLegalHold{return DB::transaction(function()use($document,$reason,$authority,$actor){$hold=DocumentLegalHold::create(['document_id'=>$document->id,'reason'=>$reason,'authority_reference'=>$authority,'placed_by'=>$actor,'placed_at'=>now()]);$document->update(['legal_hold'=>true]);app(AuditRecorder::class)->record('LEGAL_HOLD_PLACED','GOVERNANCE','SUCCESS',auth()->user(),['document_id'=>$document->id,'subject_type'=>'document','subject_ulid'=>$document->ulid,'context'=>['reason'=>$reason,'authority_reference'=>$authority]]);return $hold;});}public function release(DocumentLegalHold $hold,string $reason,int $actor):void{DB::transaction(function()use($hold,$reason,$actor){$hold->update(['released_by'=>$actor,'released_at'=>now(),'release_reason'=>$reason]);$active=DocumentLegalHold::where('document_id',$hold->document_id)->whereNull('released_at')->exists();$hold->document->update(['legal_hold'=>$active]);app(AuditRecorder::class)->record('LEGAL_HOLD_RELEASED','GOVERNANCE','SUCCESS',auth()->user(),['document_id'=>$hold->document_id,'context'=>['release_reason'=>$reason]]);});}}
